import pytest

from bedrock_protocol import v975, v1001, v2168

# generated by gophertunnel 6353c49:
# &packet.SetScoreboardIdentity{ActionType: packet.ScoreboardIdentityActionRegister,
#   Entries: []protocol.ScoreboardIdentityEntry{{EntryID: 1, EntityUniqueID: 7},
#     {EntryID: 2, EntityUniqueID: 8}}}
V1001_UPDATE = bytes.fromhex("0002020e0410")

# generated by gophertunnel 6353c49:
# &packet.SetScoreboardIdentity{ActionType: packet.ScoreboardIdentityActionClear,
#   Entries: []protocol.ScoreboardIdentityEntry{{EntryID: 1}}}
V1001_REMOVE = bytes.fromhex("010102")

# generated by gophertunnel b8bd735:
# &packet.SetScoreboardIdentity{ActionType: packet.ScoreboardIdentityActionRegister,
#   Entries: []protocol.ScoreboardIdentityEntry{{EntryID: 1, EntityUniqueID: protocol.Option(int64(7))},
#     {EntryID: 2, EntityUniqueID: protocol.Option(int64(8))}}}
V2168_UPDATE = bytes.fromhex("000202010e040110")

# generated by gophertunnel b8bd735:
# &packet.SetScoreboardIdentity{ActionType: packet.ScoreboardIdentityActionClear,
#   Entries: []protocol.ScoreboardIdentityEntry{{EntryID: 1}}}
V2168_REMOVE = bytes.fromhex("01010200")

GOLDENS = [
    pytest.param(
        v1001.SetScoreboardIdentityPacket(
            type=v1001.ScoreboardIdentityPacketType.UPDATE,
            identity_info=[
                v1001.ScoreboardIdentityPacketInfo(
                    scoreboard_id=v1001.ScoreboardId(raw_id=1),
                    player_id=v1001.PlayerScoreboardId(actor_unique_id=7),
                ),
                v1001.ScoreboardIdentityPacketInfo(
                    scoreboard_id=v1001.ScoreboardId(raw_id=2),
                    player_id=v1001.PlayerScoreboardId(actor_unique_id=8),
                ),
            ],
        ),
        V1001_UPDATE,
        id="v1001-update",
    ),
    pytest.param(
        v1001.SetScoreboardIdentityPacket(
            type=v1001.ScoreboardIdentityPacketType.REMOVE,
            removed_identity_info=[v1001.ScoreboardId(raw_id=1)],
        ),
        V1001_REMOVE,
        id="v1001-remove",
    ),
    pytest.param(
        v2168.SetScoreboardIdentityPacket(
            type=v2168.ScoreboardIdentityPacketType.UPDATE,
            identity_info=[
                v2168.ScoreboardIdentityPacketInfo(scoreboard_id=v2168.ScoreboardId(raw_id=1), player_id=7),
                v2168.ScoreboardIdentityPacketInfo(scoreboard_id=v2168.ScoreboardId(raw_id=2), player_id=8),
            ],
        ),
        V2168_UPDATE,
        id="v2168-update",
    ),
    pytest.param(
        v2168.SetScoreboardIdentityPacket(
            type=v2168.ScoreboardIdentityPacketType.REMOVE,
            identity_info=[
                v2168.ScoreboardIdentityPacketInfo(scoreboard_id=v2168.ScoreboardId(raw_id=1), player_id=None)
            ],
        ),
        V2168_REMOVE,
        id="v2168-remove",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168])
def test_set_scoreboard_identity_is_packet_112(version):
    assert version.packets[112] is version.SetScoreboardIdentityPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_scoreboard_identity_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_scoreboard_identity_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_set_scoreboard_identity_v2168_rejects_a_v1001_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.SetScoreboardIdentityPacket.from_bytes(V1001_UPDATE)


def test_set_scoreboard_identity_v1001_leaves_trailing_bytes_of_a_v2168_body():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.SetScoreboardIdentityPacket.from_bytes(V2168_UPDATE)
